import{_ as t,o,c as r,ag as a}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/notes/write-and-format-text-style.png",s="/docs/images/notes/write-and-format-show-authors.png",i="/docs/images/notes/write-and-format-more-menu-mobile.png",k=JSON.parse('{"title":"Write and format a note","description":"Write a note in Markdown, format it from the toolbar, and set up the editor the way you like.","frontmatter":{"title":"Write and format a note","description":"Write a note in Markdown, format it from the toolbar, and set up the editor the way you like.","type":"how-to"},"headers":[],"relativePath":"notes/write-and-format.md","filePath":"notes/write-and-format.md"}'),l={name:"notes/write-and-format.md"};function d(h,e,c,g,u,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="write-and-format-a-note" tabindex="-1">Write and format a note <a class="header-anchor" href="#write-and-format-a-note" aria-label="Permalink to &quot;Write and format a note&quot;">​</a></h1><p>Write a note in Markdown, format it from the toolbar, and set up the editor the way you like.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. A viewer share link opens the note read-only, in <strong>Preview</strong>.</li><li>The formatting toolbar appears in the <strong>Editor</strong> and <strong>Split</strong> layouts, not in <strong>Preview</strong>.</li><li>Images: PNG, JPEG, GIF, or WebP, up to 10 MB. In your workspace, larger images are scaled down first.</li></ul></div><h2 id="choose-a-layout" tabindex="-1">Choose a layout <a class="header-anchor" href="#choose-a-layout" aria-label="Permalink to &quot;Choose a layout&quot;">​</a></h2><ol><li>Open the note.</li><li>At the right of the toolbar, click one of the three view buttons: <strong>Editor</strong> (source only), <strong>Split</strong> (source and preview side by side), or <strong>Preview</strong> (rendered note only).</li><li>In <strong>Split</strong>, drag the divider between the panes to resize them. Each pane keeps at least 15% of the width.</li></ol><p>In <strong>Split</strong>, scrolling either pane scrolls the other to the same relative position. <strong>Preview</strong> shows the note in a centered reading column. Your layout is remembered in this browser.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p><strong>Split</strong> is not offered below 768 pixels wide. Tap the eye icon (<strong>Preview</strong>) to switch between the source and the rendered note. A layout you pick on a phone is not saved, so your desktop layout stays as it was.</p><h2 id="set-a-heading" tabindex="-1">Set a heading <a class="header-anchor" href="#set-a-heading" aria-label="Permalink to &quot;Set a heading&quot;">​</a></h2><ol><li>Put the cursor on the line.</li><li>Click <strong>Text style</strong> (it shows <strong>Normal text</strong> or the current heading) at the left of the toolbar.</li><li>Select <strong>Heading 1</strong> to <strong>Heading 6</strong>, or <strong>Normal text</strong> to remove the heading.</li></ol><p>The line gets the matching number of <code>#</code> marks. Shortcut: <code>⌘+Option+1</code> / <code>Ctrl+Alt+1</code> through <code>6</code>, and <code>0</code> for normal text.</p><p><img src="'+n+'" alt="Text style menu open with Normal text and Heading 1 to Heading 6, each showing its shortcut"></p><h2 id="make-text-bold-italic-or-struck-through" tabindex="-1">Make text bold, italic, or struck through <a class="header-anchor" href="#make-text-bold-italic-or-struck-through" aria-label="Permalink to &quot;Make text bold, italic, or struck through&quot;">​</a></h2><ol><li>Select the text.</li><li>Click <strong>Bold</strong>, <strong>Italic</strong>, or <strong>Strikethrough</strong> in the toolbar.</li></ol><p>The buttons light up when the cursor is in text that has that style. Click again to remove it. Shortcuts: <code>⌘+B</code> / <code>Ctrl+B</code>, <code>⌘+I</code> / <code>Ctrl+I</code>, and <code>⌘+Shift+X</code> / <code>Ctrl+Shift+X</code>.</p><h2 id="add-a-link" tabindex="-1">Add a link <a class="header-anchor" href="#add-a-link" aria-label="Permalink to &quot;Add a link&quot;">​</a></h2><ol><li>Select the link text.</li><li>Click <strong>Link</strong>, or press <code>⌘+K</code> / <code>Ctrl+K</code>. The text becomes <code>[text](url)</code> with <code>url</code> selected.</li><li>Type or paste the address.</li></ol><p>To remove a link, put the cursor in it and click <strong>Link</strong> again. Web addresses typed as plain text also become links in the preview.</p><h2 id="make-lists-and-checklists" tabindex="-1">Make lists and checklists <a class="header-anchor" href="#make-lists-and-checklists" aria-label="Permalink to &quot;Make lists and checklists&quot;">​</a></h2><ol><li>Select one or more lines.</li><li>Click <strong>Bullet list</strong>, <strong>Numbered list</strong>, or <strong>Checkbox</strong>.</li><li>To nest items, click <strong>Indent</strong>. To bring them back out, click <strong>Outdent</strong>.</li></ol><p>Clicking the lit list button turns the lines back into paragraphs, and clicking a different one converts the list. <strong>Indent</strong> is unavailable on the first item of a list, and <strong>Outdent</strong> on a top-level item. Press <code>Enter</code> at the end of an item to start the next one, and <code>Enter</code> on an empty item to end the list.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Type <code>[ ]</code> at the start of a line and press <code>Space</code> to start a checklist item. The editor adds the <code>- </code> for you.</p></div><h2 id="insert-a-quote-code-block-foldout-or-table" tabindex="-1">Insert a quote, code block, foldout, or table <a class="header-anchor" href="#insert-a-quote-code-block-foldout-or-table" aria-label="Permalink to &quot;Insert a quote, code block, foldout, or table&quot;">​</a></h2><ol><li>Put the cursor where you want the block, or select lines to wrap.</li><li>Click one of these: <ul><li><strong>Quote</strong> adds <code>&gt; </code> to each selected line, or removes it when every line is already quoted.</li><li><strong>Code block</strong> wraps the selection in a ``` fence. Type a language name after the opening fence to highlight it.</li><li><strong>Foldout</strong> inserts a collapsible section. Type its label between <code>&lt;summary&gt;</code> and <code>&lt;/summary&gt;</code>, and its body on the blank line below.</li><li><strong>Insert table</strong> opens a grid. Point to the size you want, up to 10 by 10, and click.</li></ul></li></ol><p>Code blocks in the preview have a <strong>Copy</strong> button in the corner. For the syntax behind each block, see the <a href="/docs/notes/markdown-reference.html">Markdown reference</a>.</p><h2 id="add-an-image" tabindex="-1">Add an image <a class="header-anchor" href="#add-an-image" aria-label="Permalink to &quot;Add an image&quot;">​</a></h2><ol><li>Put the cursor where the image should go.</li><li>Click <strong>Insert image</strong> and choose one or more files. You can also paste an image or drag it into the source pane.</li></ol><p>An <strong>Uploading</strong> label with the file name shows at the cursor until the upload finishes. The editor then inserts <code>![name](url)</code>, using the file name as the alt text. If an upload fails, a message says why.</p><h2 id="tick-tasks-in-the-preview" tabindex="-1">Tick tasks in the preview <a class="header-anchor" href="#tick-tasks-in-the-preview" aria-label="Permalink to &quot;Tick tasks in the preview&quot;">​</a></h2><ol><li>Switch to <strong>Split</strong> or <strong>Preview</strong>.</li><li>Click a task&#39;s checkbox or its text.</li></ol><p>The box ticks or unticks, and the source line changes between <code>- [ ]</code> and <code>- [x]</code>. In a read-only note the boxes don&#39;t change.</p><h2 id="find-and-replace-text" tabindex="-1">Find and replace text <a class="header-anchor" href="#find-and-replace-text" aria-label="Permalink to &quot;Find and replace text&quot;">​</a></h2><ol><li>Click in the source pane and press <code>⌘+F</code> / <code>Ctrl+F</code>. The find panel opens at the bottom of the pane.</li><li>Type what to find. Press <code>Enter</code> or <code>⌘+G</code> / <code>Ctrl+G</code> for the next match, and add <code>Shift</code> for the previous one.</li><li>To replace, type in the replace field, then click <strong>replace</strong> or <strong>replace all</strong>.</li><li>Press <code>Escape</code> to close the panel.</li></ol><h2 id="fold-a-heading-or-code-block" tabindex="-1">Fold a heading or code block <a class="header-anchor" href="#fold-a-heading-or-code-block" aria-label="Permalink to &quot;Fold a heading or code block&quot;">​</a></h2><ol><li>In the source pane, find the arrow in the gutter beside a heading or a code block.</li><li>Click the arrow. The section collapses.</li><li>Click the arrow again to expand it.</li></ol><p>Shortcut: <code>⌘+Option+[</code> / <code>Ctrl+Shift+[</code> folds the block at the cursor. See <a href="/docs/notes/keyboard-shortcuts.html#view">Keyboard shortcuts</a> for the rest.</p><h2 id="see-who-wrote-each-line" tabindex="-1">See who wrote each line <a class="header-anchor" href="#see-who-wrote-each-line" aria-label="Permalink to &quot;See who wrote each line&quot;">​</a></h2><ol><li>Click <strong>Editor settings</strong> (the sliders icon) at the right of the toolbar.</li><li>Select <strong>Show authors</strong>.</li></ol><p>A column left of the line numbers names the person who last edited each line. A run of lines by the same person is labeled once. Point to a cut-off name to see it in full. Some older text has no name, and an editor without a display name shows as <strong>Anonymous</strong>.</p><p><img src="'+s+'" alt="Source pane with the authors column showing two collaborators&#39; names beside their lines"></p><div class="warning custom-block"><p class="custom-block-title">Your name is always recorded</p><p>Every editor&#39;s display name is saved with the text they type, whether or not anyone turns on <strong>Show authors</strong>. Anyone who can open the note, including a viewer share link, can see these names. Names are self-reported, so treat them as a hint, not proof.</p></div><h2 id="use-vim-keys" tabindex="-1">Use Vim keys <a class="header-anchor" href="#use-vim-keys" aria-label="Permalink to &quot;Use Vim keys&quot;">​</a></h2><ol><li>Click <strong>Editor settings</strong>.</li><li>Under <strong>Keyboard</strong>, select <strong>Vim</strong>. Select <strong>Default</strong> to switch back.</li></ol><p>In Vim mode, <code>Escape</code> belongs to Vim. On Windows and Linux the formatting shortcuts are turned off so Vim keeps its own <code>Ctrl</code> keys. On a Mac they still work. See <a href="/docs/notes/keyboard-shortcuts.html">Keyboard shortcuts</a>.</p><p>Your layout, <strong>Show authors</strong>, and keyboard choices are remembered in this browser. Changes you make while viewing a note through a share link are not saved.</p><h2 id="format-on-a-phone" tabindex="-1">Format on a phone <a class="header-anchor" href="#format-on-a-phone" aria-label="Permalink to &quot;Format on a phone&quot;">​</a></h2><p>On a phone the toolbar keeps <strong>Undo</strong>, <strong>Redo</strong>, <strong>Text style</strong> (shown as <strong>Text</strong> or <strong>H1</strong> to <strong>H6</strong>), <strong>Bold</strong>, and <strong>Italic</strong>, plus <strong>Preview</strong> (the eye) and <strong>Editor settings</strong>. The other formatting buttons are in the ⋮ menu (<strong>More formatting options</strong>):</p><ul><li><strong>Strikethrough</strong></li><li><strong>Lists</strong>: <strong>Bullet list</strong>, <strong>Numbered list</strong>, <strong>Checkbox</strong>, <strong>Indent</strong>, <strong>Outdent</strong></li><li><strong>Insert</strong>: <strong>Link</strong>, <strong>Quote</strong>, <strong>Code block</strong>, <strong>Foldout</strong>, <strong>Table (3×3)</strong>, <strong>Image</strong></li></ul><p>The table on a phone is always 3 by 3. Add or remove rows in the source afterward.</p><p><img src="'+i+'" alt="Phone note toolbar with the More formatting options menu open showing Lists and Insert groups"></p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>There are no comments on notes. Use a doc if you need comment threads.</li><li>Uploading a <code>.md</code> file from the workspace stores it as a file, not a note. To import or export Markdown, use the <a href="/docs/developers/cli/documents.html#notes">CLI</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/notes/markdown-reference.html">Markdown reference</a> for everything the preview renders.</li><li><a href="/docs/notes/keyboard-shortcuts.html">Keyboard shortcuts</a> for every key in the editor.</li><li><a href="/docs/collaborate/edit-together.html">Edit together</a> to see how live editing and cursors work.</li><li><a href="/docs/collaborate/version-history.html">Version history</a> to restore an earlier version of a note.</li></ul>',54)])])}const b=t(l,[["render",d]]);export{k as __pageData,b as default};
